"""Check 2: head vs d3a48269a on random trees, failure points and exit actions (Hypothesis, derandomized)."""
from __future__ import annotations

import errno
import os
import sys

from hypothesis import HealthCheck, given, settings, strategies as st

from common import MODULES, describe, open_descriptors, patched, tree

sys.path.insert(0, "/Users/maxghenis/.subfleet/worktrees/20261030-005231-pr279-review-r3")
from tests.unit.test_retention_walk_descriptors import small_trees  # noqa: E402

EXC = {"os": lambda m: OSError(errno.EIO, "x"), "perm": lambda m: PermissionError(errno.EACCES, "x"),
       "missing": lambda m: FileNotFoundError(errno.ENOENT, "x"), "notdir": lambda m: NotADirectoryError(errno.ENOTDIR, "x"),
       "keyboard": lambda m: KeyboardInterrupt("x"), "runtime": lambda m: RuntimeError("x"),
       "tree": lambda m: m.TreeError("injected")}
stats = {"cases": 0, "walk_exc": 0, "repo": 0}


def run_walk(m, entries, op, kth, kind, stop):
    with tree(entries) as (_, root_fd):
        before = open_descriptors()
        calls = {"n": 0}
        exc = EXC[kind](m)
        def hit():
            calls["n"] += 1
            return calls["n"] == kth
        check = None
        targets = {"listing": (m, "_names"), "stat": (os, "stat"), "open": (m, "open_dir"), "fstat": (os, "fstat")}
        patch = targets.get(op)
        orig = getattr(*patch) if patch else None
        def fail(*a, **k):
            if hit():
                raise exc
            return orig(*a, **k)
        if op == "check":
            def check():
                if hit():
                    raise exc
        yielded, caught = [], None
        ctx = patched(*patch, fail) if patch else patched(m, "MAX_DEPTH", m.MAX_DEPTH)
        with ctx:
            it = m.walk(root_fd, check)
            try:
                for rel, stt, _, name in it:
                    yielded.append((rel, name))
                    if stop is not None and len(yielded) == stop:
                        it.close()
                        break
            except BaseException as e:  # noqa: BLE001
                caught = e
        leaked = open_descriptors() - before
        for fd in leaked:
            os.close(fd)
        return yielded, describe(caught), sorted(leaked)


@settings(max_examples=int(os.environ.get("N", "400")), derandomize=True, deadline=None, database=None,
          suppress_health_check=list(HealthCheck))
@given(entries=small_trees(), op=st.sampled_from(["listing", "stat", "check", "open", "fstat", "none"]),
       kth=st.integers(1, 6), kind=st.sampled_from(sorted(EXC)), stop=st.none() | st.integers(1, 8))
def test_walk_same(entries, op, kth, kind, stop):
    a = run_walk(MODULES["d3a"], entries, op, kth, kind, stop)
    b = run_walk(MODULES["head"], entries, op, kth, kind, stop)
    stats["cases"] += 1
    stats["walk_exc"] += a[1] is not None
    assert a[0] == b[0] and a[1] == b[1], (entries, op, kth, kind, stop, a, b)
    assert b[2] == [] and set(b[2]) <= set(a[2]), (entries, op, kth, kind, stop, a, b)


@settings(max_examples=int(os.environ.get("N", "400")), derandomize=True, deadline=None, database=None,
          suppress_health_check=list(HealthCheck))
@given(depth=st.integers(1, 4), git_at=st.none() | st.integers(0, 4), file_at=st.none() | st.integers(0, 4),
       op=st.sampled_from(["none", "open", "stat"]), kth=st.integers(1, 6), kind=st.sampled_from(sorted(EXC)))
def test_repo_same(depth, git_at, file_at, op, kth, kind):
    parts = [f"p{i}" for i in range(depth)]
    rel = "/".join(parts)
    entries = []
    for i in range(depth):
        here = "/".join(parts[: i + 1])
        entries.append((here, "f" if file_at == i else "d"))
        if file_at == i:
            break
    out = []
    for name in ("d3a", "head"):
        m = MODULES[name]
        with tree(entries) as (root, root_fd):
            if git_at is not None and git_at < len(entries) and entries[git_at][1] == "d":
                (root / entries[git_at][0] / ".git").mkdir()
            before = open_descriptors()
            calls = {"n": 0}
            exc = EXC[kind](m)
            target = {"open": (m, "open_dir"), "stat": (os, "stat")}.get(op)
            orig = getattr(*target) if target else None
            def fail(*a, **k):
                calls["n"] += 1
                if calls["n"] == kth:
                    raise exc
                return orig(*a, **k)
            ctx = patched(*target, fail) if target else patched(m, "MAX_DEPTH", m.MAX_DEPTH)
            value, caught = None, None
            with ctx:
                try:
                    value = m.RegenerableWalk(root_fd, lambda _: True)._in_repository(rel)
                except BaseException as e:  # noqa: BLE001
                    caught = e
            leaked = open_descriptors() - before
            for fd in leaked:
                os.close(fd)
            out.append((value, describe(caught), sorted(leaked)))
    stats["repo"] += 1
    assert out[0][:2] == out[1][:2], (depth, git_at, file_at, op, kth, kind, out)
    assert out[1][2] == [], out


if __name__ == "__main__":
    test_walk_same()
    test_repo_same()
    print(sys.version.split()[0], "differential ok:", stats)

