"""Check 1: P2-1 at head (descent handoff in _open_path and _conflict_dir), against d3a48269a and bc108d3ad."""
from __future__ import annotations

import errno
import os

from common import DEEP, MODULES, chain, describe, head, open_descriptors, patched, tree

print("head module:", head.__file__)


class Custom(BaseException):
    pass


def make_exc(kind):
    return {"keyboard": KeyboardInterrupt("handoff close"), "os": OSError(errno.EIO, "handoff close"),
            "custom": Custom("handoff close"), "runtime": RuntimeError("handoff close")}[kind]


def run(module, site, kind, closed_first, child_kind=None, child_closed_first=True, reuse=False):
    """Fail the close of the previous descriptor at the handoff (opened[0], when two are open).

    child_kind: also fail the close of the new child (opened[1]) during cleanup.
    reuse: after the previous descriptor's real close, open /dev/null (it takes the freed number,
    as another thread's open would) and report whether that descriptor survives.
    """
    with tree(DEEP) as (root, root_fd):
        before = open_descriptors()
        real_close = os.close
        opened = []
        real_open = module.open_dir

        def open_dir(*a, **k):
            fd = real_open(*a, **k)
            opened.append(fd)
            return fd

        state = {"fired": False, "child_fired": False, "stranger": None, "closes": []}
        injected = make_exc(kind)
        child_injected = make_exc(child_kind) if child_kind else None

        def close(fd):
            state["closes"].append(fd)
            if not state["fired"] and len(opened) == 2 and fd == opened[0]:
                state["fired"] = True
                if closed_first:
                    real_close(fd)
                    if reuse:
                        state["stranger"] = os.open(os.devnull, os.O_RDONLY)
                raise injected
            if child_injected is not None and state["fired"] and not state["child_fired"] and fd == opened[1]:
                state["child_fired"] = True
                if child_closed_first:
                    real_close(fd)
                raise child_injected
            return real_close(fd)

        reclaim = module.Reclaim({}, root / "conflicts", "label")
        caught = None
        returned = None
        with patched(module, "open_dir", open_dir), patched(os, "close", close):
            try:
                if site == "path":
                    returned = module._open_path(root_fd, "a/b")
                elif site == "conflict":
                    returned = reclaim._conflict_dir("nested")
                else:
                    returned = reclaim._set_aside_fd(root_fd, "a", "a", "new")
            except BaseException as exc:  # noqa: BLE001
                caught = exc
        stranger_alive = None
        if state["stranger"] is not None:
            try:
                os.fstat(state["stranger"])
                stranger_alive = True
            except OSError:
                stranger_alive = False
        after = open_descriptors()
        leaked = after - before - ({state["stranger"]} if stranger_alive else set())
        if isinstance(returned, int) and site != "set-aside":
            leaked.discard(returned)
            os.close(returned)
        for fd in leaked:
            os.close(fd)
        if stranger_alive:
            os.close(state["stranger"])
        dup = sorted({fd for fd in state["closes"] if state["closes"].count(fd) > 1})
        return {
            "fired": state["fired"], "identity": caught is injected,
            "caught": describe(caught), "chain": chain(caught), "leaked": sorted(leaked),
            "returned_normally": caught is None, "double_closed": dup,
            "stranger_alive": stranger_alive,
            "errors": getattr(reclaim, "errors", None) if site == "set-aside" else None,
        }


if __name__ == "__main__":
    print("== r1 inputs: KeyboardInterrupt / OSError / custom BaseException / RuntimeError from the handoff close")
    for site in ("path", "conflict", "set-aside"):
        for kind in ("keyboard", "os", "custom", "runtime"):
            for closed_first in (False, True):
                for name in ("base", "d3a", "head"):
                    r = run(MODULES[name], site, kind, closed_first)
                    print(f"{site:9} {kind:8} closed_first={closed_first!s:5} {name:4} "
                          f"identity={r['identity']!s:5} leaked={r['leaked']} returned={r['returned_normally']!s:5} "
                          f"double={r['double_closed']} caught={r['caught'] and r['caught'][0]} chain=[{r['chain']}]"
                          + (f" errors={r['errors']}" if r['errors'] else ""))
    print()
    print("== the child's own close also fails during cleanup (head)")
    for site in ("path", "conflict", "set-aside"):
        for kind in ("keyboard", "os"):
            for child_kind in ("keyboard", "os"):
                for child_closed_first in (True, False):
                    r = run(head, site, kind, True, child_kind, child_closed_first)
                    print(f"{site:9} handoff={kind:8} child={child_kind:8} child_closed_first={child_closed_first!s:5} "
                          f"identity={r['identity']!s:5} leaked={r['leaked']} returned={r['returned_normally']!s:5} "
                          f"caught={r['caught'] and r['caught'][0]} chain=[{r['chain']}]")
    print()
    print("== reuse: the freed number is taken by another open before cleanup runs (closed_first=True)")
    for site in ("path", "conflict", "set-aside"):
        for kind in ("keyboard", "os"):
            for name in ("base", "d3a", "head"):
                r = run(MODULES[name], site, kind, True, reuse=True)
                print(f"{site:9} {kind:8} {name:4} stranger_alive={r['stranger_alive']} identity={r['identity']!s:5} "
                      f"leaked={r['leaked']} double={r['double_closed']} returned={r['returned_normally']!s:5} "
                      f"caught={r['caught'] and r['caught'][0]}")

