    primary,secondary=failure(body),failure(cleanup)
    with tree(DEEP) as (_,root_fd), unchanged_descriptors(root_fd):
        expected=os.stat('a',dir_fd=root_fd,follow_symlinks=False)
        attempted=[]
        original_close=os.close
        def fstat(fd):
            raise primary
        def close(fd):
            attempted.append(fd)
            original_close(fd)
            raise secondary
        with monkeypatch.context() as patch:
            patch.setattr(os,'fstat',fstat)
            patch.setattr(os,'close',close)
            with pytest.raises(BaseException) as caught:
                rfs.open_dir('a',dir_fd=root_fd,expect=expected)
        winner=secondary if cancellation(secondary) and not cancellation(primary) else primary
        assert caught.value is winner
        if winner is secondary:
            assert caught.value.__context__ is primary
        assert len(attempted)==1

@pytest.mark.parametrize('body',['close','runtime','keyboard'])
@pytest.mark.parametrize('cleanup',['os','keyboard'])
def test_explicit_walk_exit_precedence(body,cleanup,monkeypatch):
    primary=GeneratorExit() if body=='close' else failure(body)
    secondary=failure(cleanup)
    with tree(DEEP) as (_,root_fd), unchanged_descriptors(root_fd):
        opened=[]
        attempted=[]
        original_open,original_close=rfs.open_dir,os.close
        def open_dir(*args,**kwargs):
            fd=original_open(*args,**kwargs)
            opened.append(fd)
            return fd
        def close(fd):
            attempted.append(fd)
            original_close(fd)
            if fd==opened[0]:
                raise secondary
        with monkeypatch.context() as patch:
            patch.setattr(rfs,'open_dir',open_dir)
            iterator=rfs.walk(root_fd)
            for _ in range(4):
                next(iterator)
            patch.setattr(os,'close',close)
            caught=None
            try:
                iterator.close() if body=='close' else iterator.throw(primary)
            except BaseException as exc:
                caught=exc
        if body=='close' and cleanup=='os':
            assert caught is None
        elif cleanup=='keyboard' and body!='keyboard':
            assert caught is secondary
            if body=='close':
                assert isinstance(caught.__context__,GeneratorExit)
            else:
                assert caught.__context__ is primary
        else:
            assert caught is primary
        assert attempted==opened and root_fd not in attempted
